<?php
namespace App\Http\Controllers;
use App\Models\Experience; use App\Models\Exam; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class AdminController extends Controller {
 public function index(){return view('admin.dashboard',['pending'=>Experience::whereIn('status',['pending','draft'])->count(),'published'=>Experience::published()->count(),'users'=>User::count(),'exams'=>Exam::count(),'queue'=>Experience::where('status','pending')->with(['user','exam'])->latest()->paginate(20)]);}
 public function moderate(Request $r,Experience $experience){$data=$r->validate(['decision'=>'required|in:publish,reject,corrections','reason'=>'nullable|string|max:1000']);$status=['publish'=>'published','reject'=>'rejected','corrections'=>'needs_corrections'][$data['decision']];DB::transaction(function()use($experience,$status,$data){$experience->update(['status'=>$status,'published_at'=>$status==='published'?now():null]);$this->audit('experience.'.$status,$experience,['reason'=>$data['reason']??null]);});return back()->with('success','Moderation decision saved.');}
 public function users(Request $r){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');$q=User::query()->when($r->filled('q'),fn($b)=>$b->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%')->orWhere('username','like','%'.$r->q.'%')))->when($r->filled('status'),fn($b)=>$b->where('is_active',$r->status==='active'))->orderByDesc('created_at');return view('admin.users', ['users'=>$q->paginate(25)->withQueryString()]);}
 public function updateUser(Request $r,User $user){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');abort_if($user->id===auth()->id(),403,'You cannot change your own admin account here.');$data=$r->validate(['name'=>'required|string|max:100','username'=>['required','alpha_dash','min:3','max:30',Rule::unique('users','username')->ignore($user->id)],'email'=>['required','email',Rule::unique('users','email')->ignore($user->id)],'role'=>'required|in:user,moderator,admin','is_active'=>'required|boolean']);$user->update($data);$this->audit('user.updated',$user,['role'=>$user->role,'is_active'=>$user->is_active]);return back()->with('success','User updated.');}
 public function toggleUser(User $user){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');abort_if($user->id===auth()->id(),403,'You cannot disable your own account.');$user->update(['is_active'=>!$user->is_active]);$this->audit($user->is_active?'user.activated':'user.disabled',$user);return back()->with('success',$user->is_active?'Account activated.':'Account disabled.');}
 public function deleteUser(User $user){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');abort_if($user->id===auth()->id(),403,'You cannot delete your own account.');$this->audit('user.deleted',$user,['email'=>$user->email]);$user->delete();return back()->with('success','User and related content removed according to database relationships.');}
 public function posts(Request $r){$posts=Experience::with(['user','exam'])->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('q'),fn($q)=>$q->where('title','like','%'.$r->q.'%'))->latest()->paginate(25)->withQueryString();return view('admin.posts',compact('posts'));}
 public function updatePost(Request $r,Experience $experience){$data=$r->validate(['status'=>'required|in:draft,pending,published,rejected,needs_corrections']);$experience->update(['status'=>$data['status'],'published_at'=>$data['status']==='published'?($experience->published_at??now()):null]);$this->audit('experience.admin_updated',$experience,$data);return back()->with('success','Post status updated.');}
 public function reports(){abort_unless(in_array(auth()->user()->role,['admin','moderator'],true),403);$reports=DB::table('reports')->leftJoin('users as reporters','reports.reporter_id','=','reporters.id')->leftJoin('experiences','reports.reportable_id','=','experiences.id')->where('reports.reportable_type',Experience::class)->select('reports.*','reporters.name as reporter_name','experiences.title as experience_title')->orderByRaw("CASE reports.status WHEN 'open' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END")->orderByDesc('reports.created_at')->paginate(25);return view('admin.reports',compact('reports'));}
 public function updateReport(Request $r,int $report){abort_unless(in_array(auth()->user()->role,['admin','moderator'],true),403);$data=$r->validate(['status'=>'required|in:reviewing,resolved,dismissed','resolution_note'=>'nullable|string|max:1500']);$updated=DB::table('reports')->where('id',$report)->where('reportable_type',Experience::class)->update(['status'=>$data['status'],'resolution_note'=>$data['resolution_note']??null,'resolved_by'=>auth()->id(),'updated_at'=>now()]);abort_unless($updated,404);$this->audit('report.'.$data['status'],null,['report_id'=>$report]);return back()->with('success','Report status updated.');}
 public function settings(){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');return view('admin.settings',['settings'=>DB::table('site_settings')->orderBy('key')->get()]);}
 public function saveSettings(Request $r){abort_unless(auth()->user()->role==='admin',403,'Administrator access required.');$data=$r->validate(['site_name'=>'required|string|max:100','tagline'=>'nullable|string|max:200','community_guidelines'=>'nullable|string|max:5000','maintenance_mode'=>'nullable|boolean','allow_registration'=>'nullable|boolean']);foreach(['site_name','tagline','community_guidelines','maintenance_mode','allow_registration'] as $key){$value=in_array($key,['maintenance_mode','allow_registration'])?($r->boolean($key)?'1':'0'):($data[$key]??'');DB::table('site_settings')->updateOrInsert(['key'=>$key],['value'=>$value,'type'=>in_array($key,['maintenance_mode','allow_registration'])?'boolean':'text','updated_at'=>now(),'created_at'=>now()]);}$this->audit('settings.updated',null,$data);return back()->with('success','Site settings saved.');}
 private function audit(string $action,$subject=null,array $metadata=[]):void{DB::table('admin_audit_logs')->insert(['admin_id'=>auth()->id(),'action'=>$action,'subject_type'=>$subject?get_class($subject):null,'subject_id'=>$subject?->id,'metadata'=>json_encode($metadata),'ip_address'=>request()->ip(),'created_at'=>now(),'updated_at'=>now()]);}
}
